import{_ as t,o,c as a,a3 as r}from"./chunks/framework.Ki30n65y.js";const s="/depgate/screenshots/settings-jobs.png",n="/depgate/screenshots/jobs-feeds.png",b=JSON.parse('{"title":"Jobs and data feeds","description":"","frontmatter":{},"headers":[],"relativePath":"admin/jobs.md","filePath":"admin/jobs.md"}'),d={name:"admin/jobs.md"};function i(h,e,l,u,c,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="jobs-and-data-feeds" tabindex="-1">Jobs and data feeds <a class="header-anchor" href="#jobs-and-data-feeds" aria-label="Permalink to &quot;Jobs and data feeds&quot;">​</a></h1><p>DepGate keeps its threat and vulnerability data up to date, sends webhooks and email, and removes old records with background jobs. <strong>Settings → Jobs</strong> (Security role) shows their queues and schedules; <strong>Jobs &amp; Feeds</strong> in the sidebar lists every run.</p><p><img src="'+s+'" alt="Settings → Jobs"></p><h2 id="queues" tabindex="-1">Queues <a class="header-anchor" href="#queues" aria-label="Permalink to &quot;Queues&quot;">​</a></h2><p>Work shared by every DepGate replica:</p><table tabindex="0"><thead><tr><th>Queue</th><th>Holds</th></tr></thead><tbody><tr><td><strong>Webhook deliveries</strong></td><td>Events waiting to be sent or retried.</td></tr><tr><td><strong>Scheduled jobs</strong></td><td>The scheduled jobs below.</td></tr><tr><td><strong>Email</strong></td><td>Invitation and password reset emails.</td></tr><tr><td><strong>Monitoring rechecks</strong></td><td>Re-evaluation of recorded downloads after a monitoring policy&#39;s rule changes.</td></tr></tbody></table><p>Each row shows the number of waiting, active, delayed and failed jobs. Completed jobs are removed at once.</p><p>If the job queue is unavailable, the page says so. Package downloads keep working, and webhooks and email are sent directly instead of through the queue.</p><h2 id="schedules" tabindex="-1">Schedules <a class="header-anchor" href="#schedules" aria-label="Permalink to &quot;Schedules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Job</th><th>Interval</th><th>Does</th></tr></thead><tbody><tr><td><strong>Malicious feed sync</strong></td><td>Every hour (<code>MALICIOUS_SYNC_INTERVAL_HOURS</code>)</td><td>Updates the <a href="./malware">malware list</a>.</td></tr><tr><td><strong>EPSS scores sync</strong></td><td>Every 24 hours (<code>EPSS_SYNC_INTERVAL_HOURS</code>)</td><td>Downloads the EPSS exploit-likelihood data.</td></tr><tr><td><strong>Monitoring and history retention</strong></td><td>Every hour</td><td>Removes old monitoring rows, webhook deliveries and job history.</td></tr><tr><td><strong>Ledger and audit retention</strong></td><td>Every hour</td><td>Removes <a href="./decision-ledger#retention">Decision Ledger</a> and <a href="./audit-log#retention">Audit Log</a> entries older than their retention.</td></tr><tr><td><strong>Namespace collision check</strong></td><td>Every 24 hours</td><td>Runs only while the <a href="./namespace-protection#collision-check-optional">collision check</a> is turned on.</td></tr></tbody></table><p>Each job runs once per interval for the whole installation, whatever the number of replicas. The table shows the next run and the result of the last run. Choose <strong>Run now</strong> to queue a run immediately; <strong>Run history in Jobs &amp; Feeds</strong> opens every run.</p><h3 id="epss-data" tabindex="-1">EPSS data <a class="header-anchor" href="#epss-data" aria-label="Permalink to &quot;EPSS data&quot;">​</a></h3><p>Under <strong>EPSS scores sync</strong>, a second row shows the data used by <a href="./policy-rules#exploit-likelihood-epss">Vulnerability policies</a>: the date of the scores, how many CVEs are scored, the model version and where the file came from.</p><p>DepGate downloads the full EPSS file once a day and stores it locally; policies never call an external service during a download. If the file cannot be downloaded, DepGate keeps the last good data and tries a backup source, marked <strong>GitHub backup</strong>. A note under the row and a banner on the Policies page warn when the data is older than 72 hours (<code>EPSS_STALE_AFTER_HOURS</code>).</p><h2 id="failed-jobs" tabindex="-1">Failed jobs <a class="header-anchor" href="#failed-jobs" aria-label="Permalink to &quot;Failed jobs&quot;">​</a></h2><p>Jobs that failed in the last 7 days are listed with their error, up to 500 per queue. Choose <strong>Retry</strong> to run one again, or <strong>Discard</strong> to remove it.</p><h2 id="run-history" tabindex="-1">Run history <a class="header-anchor" href="#run-history" aria-label="Permalink to &quot;Run history&quot;">​</a></h2><p>In the sidebar, choose <strong>Jobs &amp; Feeds</strong> to see what the scheduled jobs did.</p><p><img src="'+n+'" alt="The Jobs &amp; feeds page"></p><p>Each row shows when a run started, the job, what triggered it (<strong>Scheduled</strong>, <strong>Run now</strong> or <strong>Startup</strong>), its status (<strong>Succeeded</strong>, <strong>Failed</strong>, <strong>Skipped</strong> or <strong>Running</strong>), its duration and a summary of the result, such as the number of entries a feed sync added. Choose a row for the run&#39;s error and full result. Filter by time range, job, status and trigger.</p><p>Runs are kept for 90 days.</p>',21)])])}const m=t(d,[["render",i]]);export{b as __pageData,m as default};
